class NonSelfSuspendingTask:
    def __init__(self, wcet, deadline, min_inter_arrival_time):
        self.C_1 = wcet
        self.D = deadline
        self.T = min_inter_arrival_time

def calculate_total_wcet(task_i):
    total_C_i = 0
    for C_i_j in task_i.C_regions:
        total_C_i += C_i_j
    return total_C_i

class SynchronousReleaseConstraints:
    def __init__(self, self_suspending_task, higher_priority_tasks):
        self.tau_ss = self_suspending_task
        self.hp_tasks = higher_priority_tasks
        self.constraints_per_region = {} # Dictionary: {j: set_of_hp_tasks_for_region_j}

    def add_constraint(self, hp_task, region_index):
        if region_index not in self.constraints_per_region:
            self.constraints_per_region[region_index] = set()
        self.constraints_per_region[region_index].add(hp_task)

    def is_constrained_to_sync_with_region(self, hp_task, region_index):
        return region_index in self.constraints_per_region and hp_task in self.constraints_per_region[region_index]

class TransformedNonSelfSuspendingTask:
    def __init__(self, original_ss_task, wcrt_original_ss_task):
        self.C_1 = calculate_total_wcet(original_ss_task) # Sum of C_k_j
        self.D = original_ss_task.D
        self.T = original_ss_task.T
        self.J = wcrt_original_ss_task - self.C_1 # Jitter

def transform_ss_task_to_hp_interferer(ss_task_k, wcrt_k):
    return TransformedNonSelfSuspendingTask(ss_task_k, wcrt_k)
